38	export const Logs = () => {
39	  const { dagId = "", mapIndex = "-1", runId = "", taskId = "" } = useParams();
40	  const [searchParams, setSearchParams] = useSearchParams();
41	  const { t: translate } = useTranslation("dag");
42	
43	  const tryNumberParam = searchParams.get(SearchParamsKeys.TRY_NUMBER);
44	  const logLevelFilters = searchParams.getAll(SearchParamsKeys.LOG_LEVEL);
45	  const sourceFilters = searchParams.getAll(SearchParamsKeys.SOURCE);
46	  const parsedMapIndex = parseInt(mapIndex, 10);
47	
48	  const {
49	    data: taskInstance,
50	    error,
51	    isLoading,
52	  } = useTaskInstanceServiceGetMappedTaskInstance(
53	    {
54	      dagId,
55	      dagRunId: runId,
56	      mapIndex: parsedMapIndex,
57	      taskId,
58	    },
59	    undefined,
60	    {
61	      enabled: !isNaN(parsedMapIndex),
62	    },
63	  );
64	
65	  const onSelectTryNumber = (newTryNumber: number) => {
66	    if (newTryNumber === taskInstance?.try_number) {
67	      searchParams.delete(SearchParamsKeys.TRY_NUMBER);
68	    } else {
69	      searchParams.set(SearchParamsKeys.TRY_NUMBER, newTryNumber.toString());
70	    }
71	    setSearchParams(searchParams);
72	  };
73	
74	  const tryNumber = tryNumberParam === null ? taskInstance?.try_number : parseInt(tryNumberParam, 10);
75	
76	  const defaultWrap = Boolean(useConfig("default_wrap"));
77	
78	  const [wrap, setWrap] = useLocalStorage<boolean>(LOG_WRAP_KEY, defaultWrap);
79	  const [showTimestamp, setShowTimestamp] = useLocalStorage<boolean>(LOG_SHOW_TIMESTAMP_KEY, true);
80	  const [showSource, setShowSource] = useLocalStorage<boolean>(LOG_SHOW_SOURCE_KEY, false);
81	  const [fullscreen, setFullscreen] = useState(false);
82	  const [expanded, setExpanded] = useState(false);
83	
84	  const {
85	    error: logError,
86	    fetchedData,
87	    isLoading: isLoadingLogs,
88	    parsedData,
89	  } = useLogs({
90	    dagId,
91	    logLevelFilters,
92	    showSource,
93	    showTimestamp,
94	    sourceFilters,
95	    taskInstance,
96	    tryNumber,
97	  });
98	
99	  const downloadTextLines = getDownloadText({
100	    fetchedData,
101	    logLevelFilters,
102	    showSource,
103	    showTimestamp,
104	    sourceFilters,
105	    translate,
106	  });
107	
108	  const getLogString = () => downloadTextLines.filter((line) => line !== "").join("\n");
109	
110	  const [searchQuery, setSearchQuery] = useState("");
111	  const [activeSearchIndex, setActiveSearchIndex] = useState(0);
112	
113	  const searchMatchIndices = (() => {
114	    if (!searchQuery) {
115	      return [];
116	    }
117	    const query = searchQuery.toLowerCase();
118	    const indices: Array<number> = [];
119	
120	    parsedData.searchableText.forEach((line, index) => {
121	      if (line.toLowerCase().includes(query)) {
122	        indices.push(index);
123	      }
124	    });
125	
126	    return indices;
127	  })();
128	
129	  const handleSearchChange = (query: string) => {
130	    setSearchQuery(query);
131	    setActiveSearchIndex(0);
132	  };
133	
134	  const handleSearchNext = () => {
135	    if (searchMatchIndices.length > 0) {
136	      setActiveSearchIndex((prev) => (prev + 1) % searchMatchIndices.length);
137	    }
138	  };
139	
140	  const handleSearchPrevious = () => {
141	    if (searchMatchIndices.length > 0) {
142	      setActiveSearchIndex((prev) => (prev - 1 + searchMatchIndices.length) % searchMatchIndices.length);
143	    }
144	  };
145	
146	  const downloadLogs = () => {
147	    const logContent = getLogString();
148	    const element = document.createElement("a");
149	
150	    element.href = URL.createObjectURL(new Blob([logContent], { type: "text/plain" }));
151	    element.download = `logs_${taskInstance?.dag_id}_${taskInstance?.dag_run_id}_${taskInstance?.task_id}_${taskInstance?.map_index}_${taskInstance?.try_number}.txt`;
152	    document.body.append(element);
153	    element.click();
154	    element.remove();
155	  };
156	
157	  const toggleWrap = () => setWrap(!wrap);
158	  const toggleTimestamp = () => setShowTimestamp(!showTimestamp);
159	  const toggleSource = () => setShowSource(!showSource);
160	  const toggleFullscreen = () => setFullscreen(!fullscreen);
161	  const toggleExpanded = () => setExpanded((act) => !act);
162	
163	  useHotkeys("w", toggleWrap);
164	  useHotkeys("f", toggleFullscreen);
165	  useHotkeys("e", toggleExpanded);
166	  useHotkeys("t", toggleTimestamp);
167	  useHotkeys("s", toggleSource);
168	  useHotkeys("d", downloadLogs);
169	
170	  const onOpenChange = () => {
171	    setFullscreen(false);
172	  };
173	
174	  const externalLogName = useConfig("external_log_name") as string;
175	  const showExternalLogRedirect = Boolean(useConfig("show_external_log_redirect"));
176	
177	  const logHeaderProps: TaskLogHeaderProps = {
178	    downloadLogs,
179	    expanded,
180	    getLogString,
181	    onSelectTryNumber,
182	    search: {
183	      currentMatchIndex: activeSearchIndex,
184	      onSearchChange: handleSearchChange,
185	      onSearchNext: handleSearchNext,
186	      onSearchPrevious: handleSearchPrevious,
187	      searchQuery,
188	      totalMatches: searchMatchIndices.length,
189	    },
190	    showSource,
191	    showTimestamp,
192	    sourceOptions: parsedData.sources,
193	    taskInstance,
194	    toggleExpanded,
195	    toggleFullscreen,
196	    toggleSource,
197	    toggleTimestamp,
198	    toggleWrap,
199	    tryNumber,
200	    wrap,
201	  };
202	
203	  const logContentProps: TaskLogContentProps = {
204	    currentMatchLineIndex: searchMatchIndices[activeSearchIndex],
205	    error,
206	    expanded,
