import { chakra } from "@chakra-ui/react";
import type { JSX } from "react";
import * as React from "react";

import type { StructuredLogMessage } from "openapi/requests/types.gen";

/**
 * Task instance context fields that the backend injects on every structured log
 * line (identity of the task instance the log belongs to). They are identical on
 * each line, so instead of repeating them per line we surface them once via
 * {@link renderTIContextPreamble}. Must contain exactly these six field names.
 */
export const tiContextFields: Array<string> = [
  "ti_id",
  "dag_id",
  "task_id",
  "run_id",
  "try_number",
  "map_index",
];

const stringifyValue = (val: boolean | number | object | string | null | undefined): string =>
  // Let strings, ints, etc through as is, but JSON stringify anything more complex
  val instanceof Object ? JSON.stringify(val) : `${val}`;

/**
 * Collect the task instance context (the {@link tiContextFields}) from a set of
 * structured log messages. Returns an object holding the first value seen for
 * each field that is present anywhere in the content.
 */
export const getTIContext = (
  content: ReadonlyArray<string | StructuredLogMessage>,
): Record<string, unknown> => {
  const context: Record<string, unknown> = {};

  for (const datum of content) {
    if (typeof datum === "string") {
      continue; // eslint-disable-line no-continue
    }
    for (const field of tiContextFields) {
      if (!Object.hasOwn(context, field) && Object.hasOwn(datum, field)) {
        context[field] = (datum as Record<string, unknown>)[field];
      }
    }
  }

  return context;
};

/**
 * Render a preamble summarizing the task instance context fields present in
 * `context`. Only fields listed in {@link tiContextFields} are considered.
 *
 * In "text" mode a string of space-joined `key=value` pairs is returned, optionally
 * prefixed with `"${label} "`. In "jsx" mode a span is returned rendering the label
 * (if any) followed by one `key=value` entry per present field.
 */
export const renderTIContextPreamble = (
  context: Record<string, unknown>,
  renderingMode: "jsx" | "text" = "jsx",
  label?: string,
): JSX.Element | string => {
  const entries = tiContextFields
    .filter((field) => Object.hasOwn(context, field))
    .map((field) => ({
      key: field,
      value: stringifyValue(context[field] as boolean | number | object | string | null),
    }));

  if (renderingMode === "text") {
    const pairs = entries.map(({ key, value }) => `${key}=${value}`).join(" ");

    return label === undefined ? pairs : `${label} ${pairs}`;
  }

  return (
    <chakra.span lineHeight={1.5}>
      {label === undefined ? undefined : (
        <>
          <chakra.span fontWeight="bold">{label}</chakra.span>{" "}
        </>
      )}
      {entries.map(({ key, value }, entryIndex) => (
        <React.Fragment key={`ti_${key}`}>
          {entryIndex > 0 ? " " : undefined}
          <chakra.span>
            <chakra.span color="fg.info">{key}</chakra.span>={value}
          </chakra.span>
        </React.Fragment>
      ))}
    </chakra.span>
  );
};
