const ITEM_HEIGHT = 20;

beforeAll(() => {
  Object.defineProperty(HTMLElement.prototype, "offsetHeight", { value: ITEM_HEIGHT });
  Object.defineProperty(HTMLElement.prototype, "offsetWidth", { value: 800 });
});

const translate = ((key: string) => key) as unknown as TFunction;

const ctx = {
  dag_id: "log_grouping",
  map_index: -1,
  run_id: "manual__2025-02-18T12:19",
  task_id: "ti_context",
  ti_id: "01951900-16f6-7c1c-ae66-91bdfe9e0cfd",
  try_number: 1,
};

describe("tiContextFields", () => {
  it("has exactly 6 fields", () => {
    expect(tiContextFields).toEqual([
      "ti_id",
      "dag_id",
      "task_id",
      "run_id",
      "try_number",
      "map_index",
    ]);
    expect(tiContextFields).toHaveLength(6);
  });
});

describe("renderTIContextPreamble text", () => {
  it("label prefix + pairs", () => {
    const out = renderTIContextPreamble(ctx, "text", "Task Identity") as string;

    expect(out).toBe(
      "Task Identity ti_id=01951900-16f6-7c1c-ae66-91bdfe9e0cfd dag_id=log_grouping task_id=ti_context run_id=manual__2025-02-18T12:19 try_number=1 map_index=-1",
    );
  });

  it("no label => pairs only", () => {
    const out = renderTIContextPreamble(ctx, "text") as string;

    expect(out.startsWith("ti_id=")).toBe(true);
    expect(out).not.toContain("Task Identity");
  });

  it("empty context + label => label only", () => {
    expect(renderTIContextPreamble({}, "text", "Task Identity")).toBe("Task Identity ");
  });

  it("omits fields not in context", () => {
    const out = renderTIContextPreamble({ dag_id: "d" }, "text", "L") as string;

    expect(out).toBe("L dag_id=d");
  });
});

describe("UI ti_context route", () => {
  it("renders Task Identity block after source-details header, lines lack TI data attrs", async () => {
    render(
      <AppWrapper initialEntries={["/dags/log_grouping/runs/manual__2025-02-18T12:19/tasks/ti_context"]} />,
    );

    await waitFor(() => expect(screen.getByTestId("virtualized-list")).toBeInTheDocument());
    await waitFor(() => {
      const list = screen.getByTestId("virtualized-list");

      expect(
        list.querySelectorAll('[data-testid^="virtualized-item-"], [data-testid^="group-header-"]').length,
      ).toBeGreaterThan(0);
    });
    fireEvent.scroll(screen.getByTestId("virtualized-list"), { target: { scrollTop: ITEM_HEIGHT * 2 } });

    // Task Identity block visible
    await waitFor(() => expect(screen.getByText(/Task Identity/u)).toBeInTheDocument());
    expect(screen.getByText(/Task Identity/u).textContent).toContain("ti_id=01951900-16f6-7c1c-ae66-91bdfe9e0cfd");

    // DOM order: source-details header before Task Identity block
    const header = screen.getByTestId(/^summary-Log message source details/u);
    const tiBlock = screen.getByText(/Task Identity/u);

    expect(header.compareDocumentPosition(tiBlock) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();

    // Individual log lines must not carry TI data attributes
    screen.getByTestId("virtualized-list").querySelectorAll('[data-testid^="virtualized-item-"]').forEach((el) => {
      expect(el.querySelector('[data-key="ti_id"]')).toBeNull();
      expect(el.querySelector('[data-key="dag_id"]')).toBeNull();
      expect(el.querySelector('[data-key="run_id"]')).toBeNull();
    });
  }, 10_000);
});

